    const origSvgs = {};
    const themeToggle = document.getElementById('themeToggle');
    const githubLink = document.getElementById('githubLink');
    const docsBtn = document.getElementById('docsBtn');
    const iconTheme = document.getElementById('iconTheme');
    const logoEl = document.querySelector('.logo');

    origSvgs.github = githubLink ? githubLink.innerHTML : null;
    origSvgs.docs = docsBtn ? docsBtn.innerHTML : null;
    origSvgs.theme = iconTheme ? iconTheme.parentNode.innerHTML : null;
    origSvgs.logo = logoEl ? logoEl.innerHTML : null;

    // Инициализация темы
    (function initTheme() {
      const s = localStorage.getItem('kb_theme');
      applyTheme(s === 'dark', false);
    })();

    function applyTheme(dark, persist = true) {
      const html = document.documentElement;
      if (dark) {
        html.setAttribute('data-theme', 'dark');
        if (themeToggle) themeToggle.setAttribute('aria-pressed', 'true');
        if (githubLink && svgDark.github) githubLink.innerHTML = svgDark.github;
        if (docsBtn && svgDark.docs) docsBtn.innerHTML = svgDark.docs;
        if (logoEl && svgDark.logo) logoEl.innerHTML = svgDark.logo;
        if (themeToggle && svgDark.sun) themeToggle.innerHTML = svgDark.sun;
      } else {
        html.removeAttribute('data-theme');
        if (themeToggle) themeToggle.setAttribute('aria-pressed', 'false');
        if (githubLink && origSvgs.github) githubLink.innerHTML = origSvgs.github;
        if (docsBtn && origSvgs.docs) docsBtn.innerHTML = origSvgs.docs;
        if (themeToggle && origSvgs.theme) themeToggle.innerHTML = origSvgs.theme;
        if (logoEl && origSvgs.logo) logoEl.innerHTML = origSvgs.logo;
      }
      if (persist) localStorage.setItem('kb_theme', dark ? 'dark' : 'light');
    }

    if (themeToggle) {
      themeToggle.addEventListener('click', () => {
        const isDark = document.documentElement.getAttribute('data-theme') === 'dark';
        applyTheme(!isDark, true);
      });
    }

    // Graph tabs and dropzone behavior
    (function initGraphTabs() {
      const graphTabs = document.querySelectorAll('.graph-tabs a');
      const graphSvg = document.querySelector('.graph-inner > svg');
      const graphInner = document.querySelector('.graph-inner');

      function setGraphSvgVisible(visible) {
        if (!graphInner) return;
        // hide/show any inline svgs
        const svgs = graphInner.querySelectorAll('svg');
        svgs.forEach(s => {
          s.style.setProperty('display', visible ? 'block' : 'none', 'important');
          s.style.setProperty('visibility', visible ? 'visible' : 'hidden', 'important');
          s.style.setProperty('pointer-events', visible ? 'auto' : 'none', 'important');
        });
      }
      // references that may be recreated when tabs are redrawn
      let dropzone = document.getElementById('fileDropzone');
      let dropArea = document.getElementById('dropArea');
      let fileInput = document.getElementById('fileInput');
      let selectFilesBtn = document.getElementById('selectFilesBtn');
      let fileList = document.getElementById('fileList');
      let fileCards = document.getElementById('fileCards');
      // накопленный список загруженных файлов
      let uploadedFiles = [];
      const metricsPane = document.getElementById('metricsPane');
      // save original templates so we can rebuild from a clean slate
      const dropzoneTemplate = dropzone ? dropzone.innerHTML : '';
      const metricsTemplate = metricsPane ? metricsPane.innerHTML : '';
      let selectedMetrics = [];
      // expose references for run logic
      window.__kb_uploadedFiles = uploadedFiles;
      window.__kb_selectedMetrics = selectedMetrics;

      function showDropzone(show) {
        if (!dropzone || !graphInner) return;
        if (show) {
          dropzone.classList.remove('hidden');
          dropzone.classList.add('visible');
          dropzone.setAttribute('aria-hidden', 'false');
          setGraphSvgVisible(false);
          if (metricsPane) { metricsPane.style.display = 'none'; metricsPane.setAttribute('aria-hidden','true'); }
        } else {
          dropzone.classList.remove('visible');
          dropzone.classList.add('hidden');
          dropzone.setAttribute('aria-hidden', 'true');
          setGraphSvgVisible(true);
        }
      }

      function showMetrics(show) {
        if (!metricsPane || !graphInner) return;
        if (show) {
          metricsPane.style.display = 'flex';
          metricsPane.setAttribute('aria-hidden','false');
          setGraphSvgVisible(false);
          if (dropzone) { dropzone.classList.remove('visible'); dropzone.classList.add('hidden'); dropzone.setAttribute('aria-hidden','true'); }
        } else {
          metricsPane.style.display = 'none';
          metricsPane.setAttribute('aria-hidden','true');
          setGraphSvgVisible(true);
        }
      }

      // Rebuild dropzone DOM from template and reattach handlers
      function rebuildDropzone() {
        if (!dropzone) return;
        dropzone.innerHTML = dropzoneTemplate;
        // re-query recreated nodes
        dropArea = document.getElementById('dropArea');
        fileInput = document.getElementById('fileInput');
        selectFilesBtn = document.getElementById('selectFilesBtn');
        fileList = document.getElementById('fileList');
        fileCards = document.getElementById('fileCards');

        if (selectFilesBtn && fileInput) selectFilesBtn.addEventListener('click', () => fileInput.click());
        if (fileInput) fileInput.addEventListener('change', (e) => { handleFiles(e.target.files); showDropzone(true); fileInput.value = ''; });

        // drag & drop handlers
        ['dragenter', 'dragover'].forEach(evt => {
          dropArea && dropArea.addEventListener(evt, (e) => {
            e.preventDefault(); e.stopPropagation();
            dropArea.classList.add('dragover');
          });
        });
        ['dragleave', 'drop'].forEach(evt => {
          dropArea && dropArea.addEventListener(evt, (e) => {
            e.preventDefault(); e.stopPropagation();
            dropArea.classList.remove('dragover');
          });
        });
        dropArea && dropArea.addEventListener('drop', (e) => {
          const dt = e.dataTransfer;
          if (dt && dt.files && dt.files.length) {
            handleFiles(dt.files);
            showDropzone(true);
          }
        });

        renderFiles();
      }

      // Rebuild metrics pane DOM from template and reattach handlers
      function rebuildMetricsPane() {
        if (!metricsPane) return;
        metricsPane.innerHTML = metricsTemplate;
        initMetricButtons();
      }

      graphTabs.forEach(tab => {
        tab.addEventListener('click', (e) => {
          e.preventDefault();
          // fully clear previous tab DOM to avoid layering artefacts
          if (dropzone) { dropzone.classList.remove('visible'); dropzone.classList.add('hidden'); dropzone.setAttribute('aria-hidden','true'); dropzone.innerHTML = ''; }
          if (metricsPane) { metricsPane.style.display = 'none'; metricsPane.setAttribute('aria-hidden','true'); metricsPane.innerHTML = ''; }

          graphTabs.forEach(t => t.classList.remove('active'));
          tab.classList.add('active');
          const t = tab.textContent.trim();
          if (t === 'Файл') { rebuildDropzone(); showDropzone(true); }
          else if (t === 'Метрики') { rebuildMetricsPane(); showMetrics(true); }
          else { /* Запуск - nothing to rebuild, ensure panels hidden */ showMetrics(false); showDropzone(false); if (window.__kb_startRun) window.__kb_startRun(); }
        });
      });

      if (selectFilesBtn && fileInput) {
        selectFilesBtn.addEventListener('click', () => fileInput.click());
      }

      // (canvas drawing removed) Using original inline SVG instead.

      function renderFiles() {
        if (!fileList) return;
        const fileCards = document.getElementById('fileCards');
        fileList.innerHTML = '';
        if (fileCards) fileCards.innerHTML = '';
        uploadedFiles.forEach((entry, idx) => {
          const f = entry.file;
          const li = document.createElement('li');
          li.textContent = `${f.name} (${Math.round(f.size / 1024)} KB)`;
          fileList.appendChild(li);

          if (fileCards) {
            const card = document.createElement('div');
            card.className = 'file-card';

            const thumb = document.createElement('div');
            thumb.className = 'thumb';
            const ext = (f.name.split('.').pop() || '').toUpperCase();
            thumb.textContent = ext;

            const meta = document.createElement('div');
            meta.className = 'meta';
            const name = document.createElement('div');
            name.className = 'name';
            name.textContent = f.name;
            const size = document.createElement('div');
            size.className = 'size';
            size.textContent = `${Math.round(f.size / 1024)} KB`;
            meta.appendChild(name);
            meta.appendChild(size);

            const removeBtn = document.createElement('button');
            removeBtn.className = 'remove-btn';
            removeBtn.type = 'button';
            removeBtn.title = 'Удалить';
            removeBtn.textContent = '✕';
            removeBtn.addEventListener('click', () => {
              uploadedFiles.splice(idx, 1);
              renderFiles();
            });

            card.appendChild(thumb);
            card.appendChild(meta);
            card.appendChild(removeBtn);
            fileCards.appendChild(card);
          }
        });
      }

      function handleFiles(files) {
        const allowed = ['csv', 'txt'];
        Array.from(files).forEach((f) => {
          const ext = (f.name.split('.').pop() || '').toLowerCase();
          if (!allowed.includes(ext)) return; // игнорируем неподдерживаемые типы
          const exists = uploadedFiles.some(e => e.file.name === f.name && e.file.size === f.size);
          if (!exists) uploadedFiles.push({ id: Date.now() + Math.random(), file: f });
        });
        renderFiles();
      }

      // инициализация кнопок метрик — через делегирование, чтобы работать после перерисовки
      let metricsDelegationAttached = false;
      function initMetricButtons() {
        if (!metricsPane) return;
        // set initial aria-pressed for any existing buttons
        const btns = metricsPane.querySelectorAll('.metric-btn');
        btns.forEach(btn => btn.setAttribute('aria-pressed', 'false'));

        if (metricsDelegationAttached) return;
        metricsPane.addEventListener('click', (e) => {
          const btn = e.target.closest && e.target.closest('.metric-btn');
          if (!btn) return;
          e.preventDefault();
          const name = btn.getAttribute('data-metric');
          const idx = selectedMetrics.indexOf(name);
          if (idx === -1) {
            selectedMetrics.push(name);
            btn.classList.add('selected');
            btn.setAttribute('aria-pressed','true');
          } else {
            selectedMetrics.splice(idx,1);
            btn.classList.remove('selected');
            btn.setAttribute('aria-pressed','false');
          }
        });
        metricsDelegationAttached = true;
      }

      initMetricButtons();

      if (fileInput) fileInput.addEventListener('change', (e) => { handleFiles(e.target.files); showDropzone(true); });

      // Drag & drop handlers
      ['dragenter', 'dragover'].forEach(evt => {
        dropArea && dropArea.addEventListener(evt, (e) => {
          e.preventDefault(); e.stopPropagation();
          dropArea.classList.add('dragover');
        });
      });

      ['dragleave', 'drop'].forEach(evt => {
        dropArea && dropArea.addEventListener(evt, (e) => {
          e.preventDefault(); e.stopPropagation();
          dropArea.classList.remove('dragover');
        });
      });

      dropArea && dropArea.addEventListener('drop', (e) => {
        const dt = e.dataTransfer;
        if (dt && dt.files && dt.files.length) {
          handleFiles(dt.files);
          showDropzone(true);
        }
      });
    })();
    // Печатающийся текст удалён на этой странице; оставляем только логику темы и кнопок

    // --- Логика запуска анализа: показ клавиатуры и печать строк ---
    (function attachRunLogic() {
      function pressKey(letter) {
        const keys = Array.from(document.querySelectorAll('#runArea .key'));
        let matchedByTop = false;
        let matchedAny = false;

        keys.forEach(key => {
          const keyTopEl = key.querySelector('.key-top');
          const keyMainEl = key.querySelector('.key-main');
          const keyTop = keyTopEl && keyTopEl.textContent.trim();
          const keyMain = keyMainEl && keyMainEl.textContent.trim();
          const dataKey = key.getAttribute('data-key');

          if (dataKey && dataKey === (letter === ' ' ? ' ' : letter.toLowerCase())) {
            key.classList.add('pressed'); matchedAny = true; setTimeout(() => key.classList.remove('pressed'), 200); return;
          }
          if (keyMain && keyMain === letter) { key.classList.add('pressed'); matchedAny = true; setTimeout(() => key.classList.remove('pressed'), 200); return; }
          if (keyTop && keyTop === letter) { key.classList.add('pressed'); matchedByTop = true; matchedAny = true; setTimeout(() => key.classList.remove('pressed'), 200); return; }
          const full = key.textContent.trim();
          if (!matchedAny && full === letter) { key.classList.add('pressed'); matchedAny = true; setTimeout(() => key.classList.remove('pressed'), 200); }
        });

        if (matchedByTop) {
          const leftShift = Array.from(document.querySelectorAll('#runArea .key')).find(k => k.textContent.trim() === '⇧');
          if (leftShift) { leftShift.classList.add('pressed'); setTimeout(() => leftShift.classList.remove('pressed'), 200); }
        }
      }

      let runInProgress = false;
      let runAbort = false;

      function shuffleArray(arr) {
        for (let i = arr.length - 1; i > 0; i--) {
          const j = Math.floor(Math.random() * (i + 1));
          [arr[i], arr[j]] = [arr[j], arr[i]];
        }
        return arr;
      }

      async function startRun() {
    if (runInProgress) return;
    runInProgress = true; runAbort = false;

    const runArea = document.getElementById('runArea');
    const graphWrap = document.querySelector('.graph-wrap');
    const runTypedText = document.getElementById('runTypedText');
    const runCursor = document.getElementById('runCursor');

    const facts = [
      'Интересный факт: QWERTY появилась для снижения заеданий механических печатных машин.',
      'Факт: Dvorak позиционировал себя как более эффективная раскладка для скорости печати.',
      'Заметка: В разных странах распространены разные раскладки: YTSUKEN, AZERTY, QWERTZ и т.д.',
      'Клавиатуры бывают механические и мембранные; механические дают тактильный отклик.',
      'Клавиатуры бывают механические и мембранные; мембранные менее долговечны, но тише и обладают меньшим ходом клавиши.',
      'Совет: правильная постановка рук снижает усталость и увеличивает скорость печати.'
    ];

    let factQueue = shuffleArray(facts.slice());
    function nextFact() { if (factQueue.length === 0) factQueue = shuffleArray(facts.slice()); return factQueue.shift(); }

    const graphInner = document.querySelector('.graph-inner');
    if (graphInner) {
      const svgs = graphInner.querySelectorAll('svg');
      svgs.forEach(s => {
        s.style.setProperty('display', 'none', 'important');
        s.style.setProperty('visibility', 'hidden', 'important');
        s.style.setProperty('pointer-events', 'none', 'important');
      });
    }
    if (graphWrap) graphWrap.classList.add('run-active');
    if (runArea) {
      runArea.style.display = 'block';
      const rk = runArea.querySelector('.keyboard');
      if (rk) { rk.style.setProperty('z-index', '120', 'important'); rk.style.setProperty('position', 'relative', 'important'); }
    }
    if (runCursor) runCursor.classList.add('blink');

    const START_DELAY_MS = 2000;
    const KEEP_UI_ON_FINISH = true;

    function typeText(text, element, perCharDelay = 120) {
      return new Promise((resolve) => {
        let i = 0;
        function step() {
          if (runAbort) return resolve();
          if (i < text.length) {
            const ch = text[i];
            element.textContent += ch;
            pressKey(ch);
            i++;
            setTimeout(step, perCharDelay + Math.floor(Math.random() * 60));
          } else resolve();
        }
        step();
      });
    }

    // ========== отправка файлов на API ==========
    let jobId = null;
    const files = window.__kb_uploadedFiles || [];

    if (files.length > 0) {
      const formData = new FormData();
      files.forEach(entry => {
        formData.append('files', entry.file);
      });

      try {
        const resp = await fetch('/analyze', {
          method: 'POST',
          body: formData
        });
        const data = await resp.json();
        if (data.job_id) {
          jobId = data.job_id;
        }
      } catch (err) {
        console.error('Ошибка отправки файлов:', err);
      }
    }
    // ====================================================

    const metricLabels = { static: 'Статические', dynamic: 'Динамические', integration: 'Интеграционные' };
    const selArr = (window.__kb_selectedMetrics && window.__kb_selectedMetrics.length) ? window.__kb_selectedMetrics : [];
    const selLabels = (selArr && selArr.length) ? selArr.map(s => metricLabels[s] || s).join(', ') : 'ничего не выбрано';

    if (selArr){
      try {
        const resp = await fetch ('/metrics', {
          method: 'POST',
          body: selLabels.toString()
        });
        const data = await resp.json();
      } catch (err) {
        console.error('Ошибка отправки метрик:', err);
      }
    }

    let analysisDone = false;

    const lines = [];
    lines.push('Начало анализа');
    const uploaded = files.length;
    lines.push(`передано файлов (${uploaded})`);
    if (jobId) {
      lines.push(`ID задачи: ${jobId}`);
    }

    lines.push(`выбраны метрики (${selLabels})`);

    (async function runLoop() {
      await new Promise(r => setTimeout(r, START_DELAY_MS));

      for (let ln of lines) {
        if (runAbort) break;
        runTypedText.textContent = '';
        await typeText(ln, runTypedText);
        await new Promise(r => setTimeout(r, 1200 + Math.random() * 800));
        pressKey('⏎');
        await new Promise(r => setTimeout(r, 220));
        runTypedText.textContent = '';
        if (analysisDone) break;
      }

      // ========== НОВОЕ: опрос статуса вместо таймера ==========
      if (jobId) {
        while (!runAbort && !analysisDone) {
          try {
            const resp = await fetch(`/status/${jobId}`);
            const data = await resp.json();

            if (data.status === 'finished') {
              analysisDone = true;
              break;
            } else if (data.status && data.status.startsWith('error')) {
              analysisDone = true;
              runTypedText.textContent = '';
              await typeText(`Ошибка: ${data.status}`, runTypedText, 90);
              break;
            }
          } catch (err) {
            console.error('Ошибка опроса статуса:', err);
          }

          // Пока анализ идёт — показываем факты
          const fact = nextFact();
          runTypedText.textContent = '';
          await typeText(fact, runTypedText);
          await new Promise(r => setTimeout(r, 1200 + Math.random() * 800));
          pressKey('⏎');
          await new Promise(r => setTimeout(r, 220));
          runTypedText.textContent = '';

          // Ждём 3 секунды перед следующей проверкой
          await new Promise(r => setTimeout(r, 3000));
        }
      } else {
        // Если файлы не отправлялись — используем старую логику с таймером
        const ANALYSIS_DURATION_MS = 10000; // 10 секунд для демо
        setTimeout(() => { analysisDone = true; }, ANALYSIS_DURATION_MS);

        while (!runAbort && !analysisDone) {
          const fact = nextFact();
          runTypedText.textContent = '';
          await typeText(fact, runTypedText);
          await new Promise(r => setTimeout(r, 1200 + Math.random() * 800));
          pressKey('⏎');
          await new Promise(r => setTimeout(r, 220));
          runTypedText.textContent = '';
        }
      }
      // ==========================================================

      if (analysisDone) {
        runTypedText.textContent = '';
        await typeText('анализ завершён!', runTypedText, 90);
      }

      if (!KEEP_UI_ON_FINISH) {
        const graphSvgs = document.querySelectorAll('.graph-inner svg');
        graphSvgs.forEach(s => {
          s.style.removeProperty('display');
          s.style.removeProperty('visibility');
          s.style.removeProperty('pointer-events');
        });
        const graphWrap = document.querySelector('.graph-wrap');
        if (graphWrap) graphWrap.classList.remove('run-active');
        if (runArea) {
          const rk = runArea.querySelector('.keyboard');
          if (rk) { rk.style.removeProperty('z-index'); rk.style.removeProperty('position'); }
          runArea.style.display = 'none';
        }
        if (runCursor) runCursor.classList.remove('blink');
      }

      runInProgress = false;
    })();
  }


      // expose starter to outer scope so tab handler can call it
      window.__kb_startRun = startRun;
    })();